const Q=require('./aquatic'),V=require('./vertebrates'),assert=require('node:assert/strict'),fs=require('fs');const checks=[];function ck(n,v){assert.ok(v,n);checks.push(n)};let s=Q.create();ck('12 tenreques iniciais',V.metrics(s).count[4]===12);ck('52 vertebrados iniciais',V.metrics(s).total===52);let p=s.animals.find(a=>a.sp===4), site=p.pos;for(let a of s.insects.slice(0,40)){a.pos=site}p.c=.025;p.lastHunt=-100;for(let i=0;i<120;i++){Q.tick(s);assert.ok(Object.values(s.last).every(x=>Number.isFinite(x)&&Math.abs(x)<1e-6))};ck('tenreques consomem insetos reais',s.animalEvents.meals[4]>0);ck('contabilidade preservada na presença de tenreques',true);let t=Q.create(),mom=t.animals.find(a=>a.sp===4&&a.sex==='F');mom.preg=.25;mom.c=.07;mom.n=.008;Q.tick(t);ck('nascimento mamífero',t.animalEvents.births[4]===1);let young=t.animals.find(a=>a.sp===4&&a.age===0);ck('vínculo materno',young?.mother===mom.id);Q.tick(t);ck('cuidado materno',t.lifeEvents.nursed>0);fs.writeFileSync('tenrec-results.json',JSON.stringify({checks,meals:s.animalEvents.meals[4],pop:V.metrics(s)},null,2));console.log(checks)
